1	// Shared vocabulary for sfvictorian-split: the palette as named constants, the site coordinates from plan.md, and one
2	// helper per plan.md VOCABULARY item. Every helper writes through the build library (B.* states) into a Grid or a
3	// guard()/runParts() view, so a part can call the helpers it needs and nothing else.
4	//
5	// Conventions (plan.md): front is NORTH (z = 0 street, z grows south to the back fence). A stair's `facing` is the side
6	// of its full-height back. Cornice and bracket lips point at the street: half "top", facing "south" (into the wall).
7	import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
8	
9	// ---- palette (ids from palette.json; B.* adds _stairs / _slab / _trapdoor / _door / _fence / _wall) ----------------
10	export const BODY = "cyan_terracotta";            // BODY siding (sage-teal)
11	export const TRIM = "smooth_quartz";              // TRIM cream: + stairs / slab
12	export const PILLAR = "quartz_pillar";            // corner boards, column shafts
13	export const PLUM = "crimson";                    // PLUM: + planks / stairs / slab / trapdoor / door / fence
14	export const PLUM_PANEL = "purple_terracotta";    // spandrel bands
15	export const GOLD = "yellow_terracotta";          // fish scale, pediment tympanum
16	export const GOLD_ALT = "orange_terracotta";      // fish scale second tone
17	export const STONE = "stone_bricks";              // BASE stone, full block
18	export const STONE_FAMILY = "stone_brick";        // BASE stone: + _stairs / _slab / _wall
19	export const ANDESITE = "andesite";               // rustication
20	export const CHISELED = "chiseled_stone_bricks";  // string course
21	export const BRICK = "bricks";                    // party walls, chimney, full block
22	export const BRICK_FAMILY = "brick";              // party walls: + _stairs / _slab / _wall
23	export const IRON = "iron_bars";                  // fences, handrails
24	export const PANE = "glass_pane";
25	export const GLASS = "glass";                     // skylight
26	export const CONCRETE = "light_gray_concrete";    // sidewalk, drive
27	export const GRAVEL = "gravel";                   // path, roof deck
28	export const DIRT = "dirt";                       // flower-bed soil
29	export const COARSE_DIRT = "coarse_dirt";         // side borders
30	export const FARMLAND = "farmland";               // raised vegetable beds
31	export const GRASS = "grass_block";               // lawn
32	export const TIMBER_PLANKS = "spruce_planks";     // deck, bed rims
33	export const TIMBER = "spruce";                   // + stairs / slab / fence / trapdoor
34	export const LOG = "oak_log";                     // tree trunk
35	export const LEAVES = "oak_leaves";               // canopy (persistent)
36	export const AZALEA = "flowering_azalea";         // flower-bed shrub
37	export const FLOWERS = ["red_tulip", "poppy", "allium", "azure_bluet", "lilac"];
38	export const LANTERN = "lantern";
39	export const END_ROD = "end_rod";                 // finials
40	
41	// ---- site coordinates from plan.md (x 0..15 W->E, z 0 street/N -> 49 back fence, y 0 = street) ------------------
42	export const SITE = {
43	  lot: { x0: 0, x1: 15, z0: 0, z1: 49 },
44	  streetZ: 0,
45	  frontZ: 7,                  // main front wall
46	  rearZ: 30,                  // rear wall
47	  partyW: 0, partyE: 15,      // party walls
48	  parapetY: 18,
49	  deckY: 17,                  // roof deck (skylight, cornice course)
50	  cornice: { y: 17 },
51	  brackets: { y: 16 },
52	  pediment: { x0: 6, x1: 9, y: 19 },
53	  sidewalk: { x0: 0, x1: 15, z0: 0, z1: 1 },
54	  drive: { x0: 3, x1: 6, z0: 0, z1: 3 },
55	  plinth: { x0: 1, x1: 8, y0: 0, y1: 3, z0: 4, z1: 6, stringY: 3 },
56	  garageDoor: { x0: 3, x1: 6, y0: 1, y1: 3, z: 4 },
57	  bay: {
58	    y0: 4, y1: 16,
59	    rows: [{ z: 4, x0: 3, x1: 6 }, { z: 5, x0: 2, x1: 7 }, { z: 6, x0: 1, x1: 8 }],
60	    windowYs: [[5, 7], [10, 12], [14, 15]],   // S1, S2, S3 window heads (openings left air)
61	    faceWindowXs: [4, 5],                     // the face pair; the diagonals are single windows
62	    spandrelY: 9,
63	    fishScaleY: 13,
64	    cornerXs: [3, 6],
65	  },
66	  porch: { x0: 10, x1: 14, z0: 7, z1: 9, floorY: 4, voidY0: 5, voidY1: 8, ceilingY: 9, columnXs: [10, 14], columnZ: 7, wainscotXs: [9, 15], wainscotZs: [8, 9] },
67	  entry: { x0: 11, x1: 12, y: 5, z: 10, transomY: 8, casingXs: [10, 13] },
68	  stoop: { x0: 11, x1: 13, treads: [[1, 2], [2, 3], [3, 4], [4, 5]], landing: { y: 4, z: 6 }, cheekXs: [10, 14], cheekZ0: 2, cheekZ1: 6, cheekTops: [1, 2, 3, 4, 4] },
69	  ironFence: { z: 2, y: 1, segments: [[0, 2], [7, 10], [14, 15]] },   // gaps: drive 3..6, stoop 11..13
70	  flowerBeds: {
71	    westFront: { x0: 0, x1: 2, z0: 2, z1: 3 },
72	    eastFront: { x0: 7, x1: 10, z0: 2, z1: 3 },
73	    stoopSide: { x0: 14, x1: 15, z0: 2, z1: 6 },
74	    strip: { x0: 9, x1: 9, z0: 4, z1: 6 },
75	  },
76	  chimney: { x0: 0, x1: 2, z0: 12, z1: 13, y0: 18, y1: 19, capY: 20 },
77	  skylight: { x0: 6, x1: 9, z0: 15, z1: 17, y: 17 },
78	  deck: {
79	    x0: 1, x1: 14, z0: 31, z1: 35, y: 4,
80	    posts: [[1, 31], [14, 31], [1, 35], [7, 35], [14, 35]], postY: 3,
81	    railY: 5, railGap: [6, 8],
82	    steps: { x0: 6, x1: 8, y: 3, z: 36 },
83	  },
84	  tree: { x: 12, z: 41, trunkY0: 3, trunkY1: 7, canopyY0: 7, canopyY1: 10, canopyCenterY: 9, r: 3 },
85	  raisedBeds: [{ x0: 1, x1: 4, z0: 45, z1: 47 }, { x0: 11, x1: 14, z0: 45, z1: 47 }],
86	};
87	
88	// ---- small utilities --------------------------------------------------------------------------------------------
89	const span = (a, b) => {
90	  const out = [];
91	  for (let i = Math.min(a, b); i <= Math.max(a, b); i++) out.push(i);
92	  return out;
93	};
94	const at = (g, x, y, z) => g.blockAt(x, y, z).replace("minecraft:", "");   // block id without namespace
95	
96	// ---- VOCABULARY helpers -----------------------------------------------------------------------------------------
97	
98	/** siding(x,y,z): plain BODY cyan_terracotta. */
99	export function siding(g, x, y, z) {
100	  g.set(x, y, z, BODY);
101	}
102	
103	/** rusticated(box): stone_bricks fill; odd y and odd x = andesite; the string course row (plinth stringY) = chiseled. */
104	export function rusticated(g, a, b) {
105	  for (const y of span(a[1], b[1])) for (const x of span(a[0], b[0])) for (const z of span(a[2], b[2])) {
106	    const block = y === SITE.plinth.stringY ? CHISELED : y % 2 === 1 && x % 2 === 1 ? ANDESITE : STONE;
107	    g.set(x, y, z, block);
108	  }
109	}
110	
111	/** fishscale(x0,x1,y0,z): two rows at y0, y0+1. Row y0 gold with gold_alt on every 2nd x; row y0+1 is the offset. */
112	export function fishscale(g, x0, x1, y0, z) {
113	  for (const x of span(x0, x1)) {
114	    const alt = (x - x0) % 2 === 0;               // orange on the even cells of row y0
115	    g.set(x, y0, z, alt ? GOLD_ALT : GOLD);
116	    g.set(x, y0 + 1, z, alt ? GOLD : GOLD_ALT);   // offset by one: orange where row y0 is gold
117	  }
118	}
119	
120	/** spandrel(x0,x1,y,z): PLUM_PANEL row at y, with a cream bottom-slab moulding proud at z-1. */
121	export function spandrel(g, x0, x1, y, z) {
122	  for (const x of span(x0, x1)) {
123	    g.set(x, y, z, PLUM_PANEL);
124	    g.set(x, y, z - 1, ...B.slab(TRIM, "bottom"));
125	  }
126	}
127	
128	/** sill(x0..x1, y, z): cream top-slab sill (proud). */
129	export function sill(g, x0, x1, y, z) {
130	  for (const x of span(x0, x1)) g.set(x, y, z, ...B.slab(TRIM, "top"));
131	}
132	
133	/** hoodPair(x0,x1,y,z): two crimson stairs meeting at a ridge (x0 faces east, x1 faces west), cream eaves at x0-1, x1+1. */
134	export function hoodPair(g, x0, x1, y, z) {
135	  g.set(x0, y, z, ...B.stairs(PLUM, "east", "bottom"));
136	  g.set(x1, y, z, ...B.stairs(PLUM, "west", "bottom"));
137	  g.set(x0 - 1, y, z, ...B.slab(TRIM, "bottom"));
138	  g.set(x1 + 1, y, z, ...B.slab(TRIM, "bottom"));
139	}
140	
141	/** hoodSingle(x,y,z): one cream bottom-slab hood cell. */
142	export function hoodSingle(g, x, y, z) {
143	  g.set(x, y, z, ...B.slab(TRIM, "bottom"));
144	}
145	
146	/**
147	 * window(x0,x1,y0,y1,z,face): glass_pane fill in the opening; for a front face ("north", the default) casing (cream,
148	 * proud at z-1, skipped where a casing or corner board already is), a sill at y0-1 and a hood at y1+1; hood is a pair
149	 * for 2+ wide openings and a single for 1 wide, unless opts.hood is "slab" (flat cream bottom-slabs across the head).
150	 * For a rear face ("south"): flat cream bottom-slab hood at y1+1, proud at z+1; no casing, no sill.
151	 */
152	export function window(g, x0, x1, y0, y1, z, face = "north", { hood } = {}) {
153	  for (const y of span(y0, y1)) for (const x of span(x0, x1)) g.set(x, y, z, ...B.pane(PANE));
154	  const hoodY = y1 + 1;
155	  if (face === "south") {
156	    for (const x of span(x0, x1)) g.set(x, hoodY, z + 1, ...B.slab(TRIM, "bottom"));
157	    return;
158	  }
159	  for (const y of span(y0, y1)) for (const x of [x0 - 1, x1 + 1]) {
160	    if ([TRIM, PILLAR].includes(at(g, x, y, z - 1))) continue;   // neighbour's casing / corner board
161	    g.set(x, y, z - 1, TRIM);
162	  }
163	  sill(g, x0, x1, y0 - 1, z - 1);
164	  const kind = hood ?? (x1 > x0 ? "pair" : "single");
165	  if (kind === "pair") hoodPair(g, x0, x1, hoodY, z - 1);
166	  else if (kind === "single") hoodSingle(g, x0, hoodY, z - 1);
167	  else if (kind === "slab") for (const x of span(x0, x1)) hoodSingle(g, x, hoodY, z - 1);
168	}
169	
170	/** cornerBoard(x,z,y0,y1): quartz_pillar axis=y replacing the wall block. */
171	export function cornerBoard(g, x, z, y0, y1) {
172	  for (const y of span(y0, y1)) g.set(x, y, z, ...B.pillar(PILLAR, "y"));
173	}
174	
175	/** bracket(x,z,y=16): plum stair bracket, lip toward the street; a plum top-slab behind it when that cell is free. */
176	export function bracket(g, x, z, y = SITE.brackets.y) {
177	  g.set(x, y, z, ...B.stairs(PLUM, "south", "top"));
178	  if (g.isAir(x, y, z + 1)) g.set(x, y, z + 1, ...B.slab(PLUM, "top"));
179	}
180	
181	/** dentils(x0,x1,z,y=16): plum top-closed trapdoors between brackets (skip the bracket xs). */
182	export function dentils(g, x0, x1, z, y = SITE.brackets.y, brackets = []) {
183	  for (const x of span(x0, x1)) {
184	    if (brackets.includes(x)) continue;
185	    g.set(x, y, z, ...B.trapdoor(PLUM, "south", "top", false));
186	  }
187	}
188	
189	/**
190	 * cornice(cells): y17 courses. cells: [{x, z, facing = "south", corner = false}]; facing is into the wall (for the bay,
191	 * toward the bay); a corner cell of the ring uses the cream block instead of a stair.
192	 */
193	export function cornice(g, cells, y = SITE.cornice.y) {
194	  for (const { x, z, facing = "south", corner = false } of cells) {
195	    if (corner) g.set(x, y, z, TRIM);
196	    else g.set(x, y, z, ...B.stairs(TRIM, facing, "top"));
197	  }
198	}
199	
200	/**
201	 * parapet(x0,x1): BODY false-front wall at y18, z=7, with a cream coping slab at y19 on z6 and z7. The coping skips the
202	 * pediment (x6..9) and the finial cells (x0 and x15 at z7).
203	 */
204	export function parapet(g, x0 = 0, x1 = 15) {
205	  const { x0: px0, x1: px1, y } = SITE.pediment;
206	  for (const x of span(x0, x1)) {
207	    g.set(x, SITE.parapetY, SITE.frontZ, BODY);
208	    if (x >= px0 && x <= px1) continue;
209	    g.set(x, y, SITE.frontZ - 1, ...B.slab(TRIM, "bottom"));
210	    if (x !== SITE.partyW && x !== SITE.partyE) g.set(x, y, SITE.frontZ, ...B.slab(TRIM, "bottom"));
211	  }
212	}
213	
214	/** pediment(x0..x1): stepped crest at y19 z7 (stairs at the ends, gold in the middle), cream crown slab at y20. */
215	export function pediment(g, x0 = SITE.pediment.x0, x1 = SITE.pediment.x1) {
216	  const { y } = SITE.pediment;
217	  g.set(x0, y, SITE.frontZ, ...B.stairs(TRIM, "east", "bottom"));
218	  g.set(x1, y, SITE.frontZ, ...B.stairs(TRIM, "west", "bottom"));
219	  for (const x of span(x0 + 1, x1 - 1)) {
220	    g.set(x, y, SITE.frontZ, GOLD);
221	    g.set(x, y + 1, SITE.frontZ, ...B.slab(TRIM, "bottom"));
222	  }
223	}
224	
225	/** finial(x): cream post at (x,19,7) with an end rod above it. */
226	export function finial(g, x) {
227	  g.set(x, SITE.pediment.y, SITE.frontZ, TRIM);
228	  g.set(x, SITE.pediment.y + 1, SITE.frontZ, END_ROD, { facing: "up" });
229	}
230	
231	/** column(x,z=7): cream base slab y5, quartz shaft y6..7, cream capital stair y8 (lip outward). */
232	export function column(g, x, z = SITE.porch.columnZ) {
233	  g.set(x, 5, z, ...B.slab(TRIM, "bottom"));
234	  g.set(x, 6, z, ...B.pillar(PILLAR, "y"));
235	  g.set(x, 7, z, ...B.pillar(PILLAR, "y"));
236	  g.set(x, 8, z, ...B.stairs(TRIM, "south", "top"));
237	}
238	
239	/** porchWainscot(): cream bottom-slabs at y5 on the porch side walls, z8..9. */
240	export function porchWainscot(g) {
241	  for (const x of SITE.porch.wainscotXs) for (const z of SITE.porch.wainscotZs) g.set(x, 5, z, ...B.slab(TRIM, "bottom"));
242	}
243	
244	/**
245	 * entryDoor(): two crimson doors in the porch back wall z=10 (lower at y5, upper at y6), hinges outward, a glass transom
246	 * at y8, cream casing at x10 and x13 for y5..8.
247	 */
248	export function entryDoor(g) {
249	  const { x0, x1, y, z, transomY, casingXs } = SITE.entry;
250	  const hinges = ["left", "right"];
251	  span(x0, x1).forEach((x, i) => {
252	    g.set(x, y, z, ...B.door(PLUM, "north", "lower", hinges[i]));
253	    g.set(x, y + 1, z, ...B.door(PLUM, "north", "upper", hinges[i]));
254	  });
255	  for (const x of span(x0, x1)) g.set(x, transomY, z, ...B.pane(PANE));
256	  for (const x of casingXs) for (const yy of span(y, transomY)) g.set(x, yy, z, TRIM);
257	}
258	
259	/**
260	 * garageDoor(): plum panelled door filling the garage opening (x3..6, y1..3, z4). Raised panels are closed plum
261	 * trapdoors on the outer face z=3, alternating columns by row; a cream lintel slab across the top at y4, z=3.
262	 */
263	export function garageDoor(g) {
264	  const { x0, x1, y0, y1, z } = SITE.garageDoor;
265	  for (const y of span(y0, y1)) for (const x of span(x0, x1)) g.set(x, y, z, ...B.block(`${PLUM}_planks`));
266	  for (const y of span(y0, y1)) {
267	    const cols = y % 2 === 1 ? [x0, x0 + 2] : [x0 + 1, x0 + 3];
268	    for (const x of cols) g.set(x, y, z - 1, ...B.trapdoor(PLUM, "north", "bottom", false));
269	  }
270	  for (const x of span(x0, x1)) g.set(x, y1 + 1, z - 1, ...B.slab(TRIM, "bottom"));
271	}
272	
273	/**
274	 * stoop(): stone steps rising south from the sidewalk to the landing at y4 z6 (treads at [y,z] in SITE.stoop), solid
275	 * stone under each step, stone cheeks at x10 and x14 with an iron handrail one above the cheek top.
276	 */
277	export function stoop(g) {
278	  const s = SITE.stoop;
279	  for (const x of span(s.x0, s.x1)) {
280	    for (const [y, z] of s.treads) {
281	      g.set(x, y, z, ...B.stairs(STONE_FAMILY, "south", "bottom"));
282	      for (const yy of span(0, y - 1)) g.set(x, yy, z, STONE);
283	    }
284	    for (const yy of span(0, s.landing.y - 1)) g.set(x, yy, s.landing.z, STONE);
285	    g.set(x, s.landing.y, s.landing.z, STONE);
286	  }
287	  s.cheekXs.forEach((x) => {
288	    span(s.cheekZ0, s.cheekZ1).forEach((z, i) => {
289	      const top = s.cheekTops[i];
290	      for (const y of span(1, top)) g.set(x, y, z, STONE);
291	      g.set(x, top + 1, z, IRON);
292	    });
293	  });
294	}
295	
296	/**
297	 * bayWall(y0,y1): BODY siding on the angled bay's wall cells (plan rows z4 x3..6; diagonals (2,5),(7,5),(1,6),(8,6))
298	 * for y0..y1. Window openings are left air: the face cells x4..5 and every diagonal inside a window head range.
299	 */
300	export function bayWall(g, y0, y1) {
301	  const { rows, windowYs, faceWindowXs } = SITE.bay;
302	  const inWindow = (y) => windowYs.some(([a, b]) => y >= a && y <= b);
303	  for (const row of rows) for (const x of span(row.x0, row.x1)) {
304	    for (const y of span(y0, y1)) {
305	      const onFace = row === rows[0];
306	      const opening = inWindow(y) && (onFace ? faceWindowXs.includes(x) : true);
307	      if (opening) continue;
308	      g.set(x, y, row.z, BODY);
309	    }
310	  }
311	}
312	
313	/**
314	 * ironFence(x0,x1,z=2): stone curb at y0 under an iron rail at y1; every third cell (from x0) is a stone wall post
315	 * instead of bars.
316	 */
317	export function ironFence(g, x0, x1, z = SITE.ironFence.z) {
318	  const y = SITE.ironFence.y;
319	  for (const x of span(x0, x1)) {
320	    g.set(x, y - 1, z, STONE);
321	    if ((x - x0) % 3 === 0) g.set(x, y, z, ...B.wall(STONE_FAMILY));
322	    else g.set(x, y, z, IRON);
323	  }
324	}
325	
326	/**
327	 * flowerBed(x0,x1,z0,z1,y=0): dirt soil at y, flowers at y+1 cycling through FLOWERS (lilac is two tall); one azalea
328	 * shrub at the first corner.
329	 */
330	export function flowerBed(g, x0, x1, z0, z1, y = 0) {
331	  for (const x of span(x0, x1)) for (const z of span(z0, z1)) {
332	    g.set(x, y, z, DIRT);
333	    const kind = FLOWERS[(x - x0 + z - z0) % FLOWERS.length];
334	    if (kind === "lilac") {
335	      g.set(x, y + 1, z, "lilac", { half: "lower" });
336	      g.set(x, y + 2, z, "lilac", { half: "upper" });
337	    } else {
338	      g.set(x, y + 1, z, kind);
339	    }
340	  }
341	  g.set(x0, y + 1, z0, AZALEA);
342	}
343	
344	/**
345	 * deck(d = SITE.deck): spruce fence posts at y3 on the plan cells, spruce deck planks at y4 over x1..14 z31..35, a
346	 * spruce stair fascia at y3 round the outer edge (not the house side), a bare spruce-fence rail at y5 on z=35 (gap at
347	 * x6..8) and on x=1 and x=14, and one spruce step down at y3 z36 (x6..8).
348	 */
349	export function deck(g, d = SITE.deck) {
350	  const posts = new Set(d.posts.map(([x, z]) => `${x},${z}`));
351	  const [gapA, gapB] = d.railGap;
352	  for (const x of span(d.x0, d.x1)) for (const z of span(d.z0, d.z1)) g.set(x, d.y, z, ...B.block(TIMBER_PLANKS));
353	  for (const [x, z] of d.posts) g.set(x, d.postY, z, ...B.fence(TIMBER));
354	  // fascia: top-half stairs at y3 under the outer edge (south, east, west); the house side is left alone
355	  for (const x of span(d.x0, d.x1)) if (!posts.has(`${x},${d.z1}`)) g.set(x, d.y - 1, d.z1, ...B.stairs(TIMBER, "south", "top"));
356	  for (const z of span(d.z0, d.z1)) for (const [x, facing] of [[d.x0, "west"], [d.x1, "east"]]) {
357	    if (!posts.has(`${x},${z}`)) g.set(x, d.y - 1, z, ...B.stairs(TIMBER, facing, "top"));
358	  }
359	  for (const x of span(d.x0, d.x1)) if (x < gapA || x > gapB) g.set(x, d.railY, d.z1, ...B.fence(TIMBER));
360	  for (const z of span(d.z0, d.z1)) for (const x of [d.x0, d.x1]) g.set(x, d.railY, z, ...B.fence(TIMBER));
361	  const st = d.steps;
362	  for (const x of span(st.x0, st.x1)) g.set(x, st.y, st.z, ...B.stairs(TIMBER, "north", "bottom"));
363	}
364	
365	/**
366	 * tree(t = SITE.tree): oak trunk (axis y) from trunkY0 to trunkY1 at (x,z); persistent oak canopy of radius r centred
367	 * on canopyCenterY, clipped to canopyY0..canopyY1, trunk cells kept; the edge is varied by a cheap parity rule.
368	 */
369	export function tree(g, t = SITE.tree) {
370	  for (const y of span(t.trunkY0, t.trunkY1)) g.set(t.x, y, t.z, ...B.log("oak", "y"));
371	  for (const y of span(t.canopyY0, t.canopyY1)) for (const x of span(t.x - t.r, t.x + t.r)) for (const z of span(t.z - t.r, t.z + t.r)) {
372	    const dx = x - t.x, dy = y - t.canopyCenterY, dz = z - t.z;
373	    const d2 = dx * dx + dy * dy + dz * dz, r2 = t.r * t.r;
374	    if (d2 > r2 || (x === t.x && z === t.z && y <= t.trunkY1)) continue;
375	    if (d2 > r2 - 2 && (dx + dy + dz) % 2 === 0) continue;                     // ragged edge
376	    g.set(x, y, z, LEAVES, { persistent: "true" });
377	  }
378	}
379	
380	/** chimney(c = SITE.chimney): brick stack on the west party wall, stone cap slab at y20, two brick-wall pots. */
381	export function chimney(g, c = SITE.chimney) {
382	  for (const x of span(c.x0, c.x1)) for (const z of span(c.z0, c.z1)) for (const y of span(c.y0, c.y1)) g.set(x, y, z, BRICK);
383	  for (const x of span(c.x0, c.x1)) for (const z of span(c.z0, c.z1)) g.set(x, c.capY, z, ...B.slab(STONE_FAMILY, "top"));
384	  g.set(1, c.capY + 1, 12, ...B.wall(BRICK_FAMILY));
385	  g.set(1, c.capY + 1, 13, ...B.wall(BRICK_FAMILY));
386	}
387	
388	/** skylight(s = SITE.skylight): glass in the deck opening, cream bottom-slab curb at y18 around it. */
389	export function skylight(g, s = SITE.skylight) {
390	  for (const x of span(s.x0, s.x1)) for (const z of span(s.z0, s.z1)) g.set(x, s.y, z, GLASS);
391	  for (const x of span(s.x0 - 1, s.x1 + 1)) for (const z of span(s.z0 - 1, s.z1 + 1)) {
392	    const inside = x >= s.x0 && x <= s.x1 && z >= s.z0 && z <= s.z1;
393	    if (!inside) g.set(x, s.y + 1, z, ...B.slab(TRIM, "bottom"));
394	  }
395	}
396	
397	/**
398	 * gardenBed(x0,x1,z0,z1): raised bed. Farmland soil at y4 over the box, spruce-plank rim at y3 round the outside.
399	 * (Not in plan.md VOCABULARY; added from elements.md item 15/17.)
400	 */
401	export function gardenBed(g, x0, x1, z0, z1) {
402	  for (const x of span(x0, x1)) for (const z of span(z0, z1)) g.set(x, 4, z, FARMLAND);
403	  for (const x of span(x0 - 1, x1 + 1)) for (const z of span(z0 - 1, z1 + 1)) {
404	    const inside = x >= x0 && x <= x1 && z >= z0 && z <= z1;
405	    if (!inside) g.set(x, 3, z, ...B.block(TIMBER_PLANKS));
406	  }
407	}
408

