  // floor slabs and the roof deck over the interior footprint
  for (const x of span(1, 14)) for (const z of span(8, 29)) for (const y of [0, 4, 9, 13, 17]) {
    const block = floorAt(x, y, z);
    if (block && !isAir(x, y, z)) g.set(x, y, z, block);
