  // interior partitions (plan ROOMS): x=9 across storeys 1-2 (z8..9 is the porch side wall, left to P2)
  place(g, [9, 9, 5, 8, 10, 22], PARTITION);
  place(g, [9, 9, 10, 12, 10, 22], PARTITION);
